//! Compare mode-3 constructor/adoption join to retained original-instruction rows.
use spore_core::{cell_fresh_save_adoption_join_v1::project,cell_save_ownership_projection_v1::Action};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let path=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(path).unwrap();assert_eq!(b.len(),568);let vtable=w(&b,0);assert_ne!(vtable,0);for i in 0..2{let row=&b[i*284..(i+1)*284];let cw=if i==0{0x27f}else{0x37f};let old=if i==0{None}else{Some(1)};let x=project([0xa5;0xec],2,old,vtable,0x55667788,0x11223344,0x12345678,cw,0x1f80,true).unwrap();assert_eq!(&x.object[..],&row[..236],"full object {i}");let counts:Vec<_>=(0..10).map(|j|w(row,236+j*4)).collect();assert_eq!(counts,vec![1,1,1,1,1,1,1,1,1,i as u32]);assert_eq!(x.adoption.root_5190,Some(2));assert_eq!(x.adoption.root_51da,0);let mut actions=vec![Action::FreshLookup,Action::Retain(2),Action::Store(Some(2))];if i==1{actions.push(Action::Release(1));}assert_eq!(x.adoption.actions,actions);let fp=w(row,276);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,280)&!0x3f,0x1f80);}println!("matched 2 retained mode-3 constructor/adoption rows; helper effects and vtable scripted");}
